#!/usr/bin/env python3
"""Bounded official ANU NH queries and offline FO/NH nominal-sensitivity replay.

Default execution is offline and never mutates an existing receipt. --online
allows at most the five specified NH POSTs, once each, with no retry. Two failed
fixed-point diagnostic controls stop the route. All evidence is archived in the
new receipt, including compressed exact response bytes and this complete code.
"""
from __future__ import annotations

import argparse
import base64
import gzip
import hashlib
import json
import re
from datetime import datetime,timezone
from decimal import Decimal,getcontext
from html.parser import HTMLParser
from pathlib import Path
from urllib.error import HTTPError
from urllib.parse import urlencode,urlparse
from urllib.request import Request,HTTPRedirectHandler,build_opener

getcontext().prec=40
ROOT=Path(__file__).resolve().parents[4]
HERE=Path(__file__).resolve().parent
RUN=ROOT/'outputs/learning-daily/20261007-DAY8-angular-momentum-selection-rules-multipolarity-run-01'
INPUT=RUN/'day9-independent-icc-readiness.json'
OUT=RUN/'day9-vacancy-sensitivity.json'
URL='https://bricc.anu.edu.au/'
ORDER=('B1-I18-401p2','B1-I18-389p6','B1-I18-757p4','B2-I15-199p6','B2-I15-382p0')
ALLOWED={'B1-I18-401p2':('401.2','M1'),'B1-I18-389p6':('389.6','M1'),
         'B1-I18-757p4':('757.4','E2'),'B2-I15-199p6':('199.6','M1'),'B2-I15-382p0':('382.0','E2')}


class AuthenticationFailure(ValueError):
    def __init__(self,cause,detail):
        super().__init__(detail)
        self.cause=cause


class SameOriginRedirect(HTTPRedirectHandler):
    def redirect_request(self,req,fp,code,msg,headers,newurl):
        target=urlparse(newurl)
        if target.scheme!='https' or target.hostname!='bricc.anu.edu.au':
            raise HTTPError(newurl,code,'outside authorized HTTPS calculator origin',headers,fp)
        return super().redirect_request(req,fp,code,msg,headers,newurl)


class Tables(HTMLParser):
    def __init__(self):
        super().__init__()
        self.skip=0;self.incell=False;self.cell=[];self.row=[];self.rows=[];self.text=[]
    def handle_starttag(self,tag,attrs):
        if tag in ('script','style'):self.skip+=1
        if tag=='tr':self.row=[]
        if tag in ('td','th'):self.incell=True;self.cell=[]
    def handle_endtag(self,tag):
        if tag in ('script','style'):self.skip=max(0,self.skip-1)
        if tag in ('td','th'):
            self.incell=False;self.row.append(' '.join(self.cell))
        if tag=='tr' and self.row:self.rows.append(self.row)
    def handle_data(self,data):
        if not self.skip and data.strip():
            self.text.append(data.strip())
            if self.incell:self.cell.append(data.strip())


def packed(body):
    return {'sha256':hashlib.sha256(body).hexdigest(),'bytes':len(body),
            'gzip_base64':base64.b64encode(gzip.compress(body,mtime=0)).decode('ascii')}


def unpacked(archive):
    body=gzip.decompress(base64.b64decode(archive['gzip_base64']))
    if hashlib.sha256(body).hexdigest()!=archive['sha256'] or len(body)!=archive['bytes']:
        raise ValueError('response archive identity mismatch')
    return body


def nds(parts):
    text=' '.join(parts).strip()
    if not text:return {'reported':'','value':None,'uncertainty_abs':None}
    match=re.fullmatch(r'([0-9]+(?:\.[0-9]+)?(?:E[+-]?[0-9]+)?)\s*(?:\(([0-9]+)\))?',text,re.I)
    if not match:raise AuthenticationFailure('coefficient_parse_failed',f'unsupported value {text}')
    value=Decimal(match[1])
    uncertainty=Decimal(match[2])*Decimal(10)**value.as_tuple().exponent if match[2] else None
    return {'reported':text,'value':str(value),'uncertainty_abs':None if uncertainty is None else str(uncertainty)}


def parse_output(body,case_id,expected_model):
    energy,mode=ALLOWED[case_id]
    parser=Tables()
    try:parser.feed(body.decode('utf-8'))
    except UnicodeError as error:raise AuthenticationFailure('response_encoding_failed',str(error))
    indices=[i for i,row in enumerate(parser.rows) if row and row[0].startswith('BrIccS v')]
    if not indices:raise AuthenticationFailure('no_program_backend_version','No actual program version/result table; selected form options or HTTP200 do not authenticate a calculation.')
    rows=parser.rows[indices[0]:]
    version=rows[0][0]
    text='\n'.join(' '.join(row) for row in rows)
    data=re.search(r'Data Sets:\s*(BrIcc[A-Za-z]+)\b',text)
    if not data:raise AuthenticationFailure('no_program_dataset_identity','No actual result Data Sets header.')
    if data[1]!=expected_model:raise AuthenticationFailure('program_dataset_mismatch',f'actual program dataset {data[1]}, expected {expected_model}')
    atomic=re.search(r'Z=([0-9]+)\b',text)
    if not atomic or atomic[1]!='60':raise AuthenticationFailure('program_Z_mismatch','Returned program Z does not authenticate Z60.')
    returned_energy=re.search(r'γ-energy:\s*([0-9.]+)\s*keV',text)
    if not returned_energy or Decimal(returned_energy[1])!=Decimal(energy):raise AuthenticationFailure('program_energy_mismatch','Returned gamma energy differs or is absent.')
    if ['Shell','E(ce)',mode] not in rows:raise AuthenticationFailure('program_mode_mismatch','No exact returned pure-mode shell-table column.')
    shells={}
    for row in rows:
        if len(row)>=3 and re.fullmatch(r'Tot|K|[LMNOPQ](?:[1-9]|-tot)',row[0]):
            shells[row[0]]={'electron_energy_keV':row[1] or None,**nds(row[2:])}
    if 'Tot' not in shells or shells['Tot']['value'] is None or 'K' not in shells or shells['K']['value'] is None:
        raise AuthenticationFailure('no_usable_Tot_K','No authenticated numerical Tot and K values.')
    total,k=Decimal(shells['Tot']['value']),Decimal(shells['K']['value'])
    if not total>=k>0:raise AuthenticationFailure('coefficient_order_failed','Tot/K positivity or ordering fails.')
    major_sum=sum(Decimal(record['value']) for name,record in shells.items()
                  if (name=='K' or name.endswith('-tot')) and record['value'] is not None)
    uncertainty=shells['Tot']['uncertainty_abs']
    if uncertainty is None or abs(total-major_sum)>Decimal(uncertainty):
        raise AuthenticationFailure('major_shell_sum_inconsistent','Major-shell sum falls outside printed Tot uncertainty/rounding.')
    warnings=list(dict.fromkeys(line for line in parser.text if 'could not' in line))
    missing=[name for name,record in shells.items() if record['value'] is None]
    return {'id':case_id,'Z':60,'energy_keV':energy,'mode':mode,'program_model':data[1],
            'program_version':version,'alpha_T':shells['Tot'],'alpha_K':shells['K'],'shells':shells,
            'warnings':warnings,'missing_rows':missing,'returned_shell_coverage_complete':not(warnings or missing),
            'major_shell_sum':str(major_sum),'total_minus_major_sum':str(total-major_sum),
            'authentication':'actual backend version + result dataset/Z/energy + exact mode column + positive numerical Tot/K; not input echo',
            'response_sha256':hashlib.sha256(body).hexdigest()}


def request_params(input_snapshot,case_id):
    energy,mode=ALLOWED[case_id]
    record=next(item for item in input_snapshot['requests']
                if item['params'].get('dataset')=='BrIccFO' and item['params'].get('energy')==energy
                and item['params'].get('multipole')==mode)
    if record['url']!=URL or record.get('method')!='POST':raise ValueError('verified origin/protocol mismatch')
    params=dict(record['params']);params['dataset']='BrIccNH'
    if params['atomic']!='60':raise ValueError('authorized Z mismatch')
    return params


def query_once(input_snapshot,case_id,attempt_number):
    params=request_params(input_snapshot,case_id)
    encoded=urlencode(params).encode('ascii')
    stem=HERE/(f'nh-{attempt_number:02d}-{case_id}')
    request_path=stem.with_name(stem.name+'-request.json')
    request_record={'url':URL,'method':'POST','params':params,'body_sha256':hashlib.sha256(encoded).hexdigest(),
                    'body_ascii':encoded.decode('ascii'),'attempt_number':attempt_number,
                    'timestamp_utc':datetime.now(timezone.utc).isoformat(),'retries':0,'credentials_or_SSL_changes':False}
    with request_path.open('x',encoding='utf-8') as stream:json.dump(request_record,stream,indent=2)
    body=b''
    http={'status':None,'final_url':None,'request_url':URL}
    transport_failure=None
    opener=build_opener(SameOriginRedirect())
    try:
        request=Request(URL,data=encoded,headers={'User-Agent':'Mozilla/5.0','Content-Type':'application/x-www-form-urlencoded'})
        with opener.open(request,timeout=30) as response:
            http['status']=response.status;http['final_url']=response.geturl()
            http['content_type']=response.headers.get('Content-Type')
            body=response.read(2_000_001)
        if len(body)>2_000_000:raise ValueError('bounded response-size limit exceeded')
    except HTTPError as error:
        http['status']=error.code;http['final_url']=error.url
        body=error.read(2_000_000)
        transport_failure={'cause':'HTTP_failure','detail':f'HTTP {error.code}'}
    except Exception as error:
        transport_failure={'cause':'transport_or_size_failure','detail':str(error)}
    html_path=stem.with_suffix('.html')
    with html_path.open('xb') as stream:stream.write(body)
    parsed=None;failure=transport_failure
    if failure is None:
        try:parsed=parse_output(body,case_id,'BrIccNH')
        except AuthenticationFailure as error:failure={'cause':error.cause,'detail':str(error)}
    record={'case_id':case_id,'request':request_record,'http':http,'response':packed(body),
            'response_path':str(html_path.relative_to(ROOT)),'parsed_NH':parsed,'failure':failure}
    with stem.with_name(stem.name+'-result.json').open('x',encoding='utf-8') as stream:
        json.dump(record,stream,ensure_ascii=False,indent=2)
    print(json.dumps({'NH_attempt':attempt_number,'case':case_id,'status':'authenticated' if parsed else 'failed',
                      'model':None if parsed is None else parsed['program_model'],
                      'version':None if parsed is None else parsed['program_version'],
                      'failure':failure},ensure_ascii=False),flush=True)
    return record


def compare(input_snapshot,fo,nh):
    comparisons={}
    for mother,old in input_snapshot['forward_comparison'].items():
        branches=[(row['lookup_id'],Decimal(row['fraction_as_given'])) for row in old['rows']]
        assert sum(fraction for _,fraction in branches)==1
        dg_fo=sum(fraction*(1+Decimal(fo[key]['alpha_T']['value'])) for key,fraction in branches)
        assert dg_fo==Decimal(old['D_photon'])
        complete=all(key in nh for key,_ in branches)
        dg_nh=sum(fraction*(1+Decimal(nh[key]['alpha_T']['value'])) for key,fraction in branches) if complete else None
        rows=[]
        for key,fraction in branches:
            if key not in nh:
                rows.append({'id':key,'status':'NH-unavailable; no replacement or FO fill'});continue
            af,an=Decimal(fo[key]['alpha_T']['value']),Decimal(nh[key]['alpha_T']['value'])
            kf,kn=Decimal(fo[key]['alpha_K']['value']),Decimal(nh[key]['alpha_K']['value'])
            beta_fo=fraction/(1+af);beta_nh=fraction/(1+an)
            total_factor=beta_nh/beta_fo
            photon_fo=fraction/dg_fo;photon_nh=fraction/dg_nh if complete else None
            photon_factor=dg_fo/dg_nh if complete else None
            rows.append({'id':key,'fraction_number':str(fraction),
                         'FO_Tot':fo[key]['alpha_T'],'NH_Tot':nh[key]['alpha_T'],
                         'FO_K':fo[key]['alpha_K'],'NH_K':nh[key]['alpha_K'],
                         'alpha_T_NH_over_FO_minus1_percent':str(100*(an/af-1)),
                         'alpha_K_NH_over_FO_minus1_percent':str(100*(kn/kf-1)),
                         'tau_gamma_rate_if_total_beta_FO':str(beta_fo),'tau_gamma_rate_if_total_beta_NH':str(beta_nh),
                         'nominal_rate_and_B_NH_over_FO_if_total_beta':str(total_factor),
                         'nominal_percent_if_total_beta':str(100*(total_factor-1)),
                         'tau_gamma_rate_if_photon_g_FO':str(photon_fo),
                         'tau_gamma_rate_if_photon_g_NH':None if photon_nh is None else str(photon_nh),
                         'nominal_rate_and_B_NH_over_FO_if_photon_g':None if photon_factor is None else str(photon_factor),
                         'nominal_percent_if_photon_g':None if photon_factor is None else str(100*(photon_factor-1)),
                         'FO_coverage_warnings':fo[key]['warnings'],'NH_coverage_warnings':nh[key]['warnings']})
        comparisons[mother]={'same_given_fractions_as_two_hypotheses':True,'tau_given_unchanged':old['tau_given'],
                             'output_rate_unit':'dimensionless tau*Tgamma; B sensitivity uses the same multiplier at fixed E,mode,tau,fraction',
                             'Dg_FO':str(dg_fo),'Dg_NH':None if dg_nh is None else str(dg_nh),
                             'complete_NH_parent_inventory':complete,'rows':rows,
                             'not_author_method_identification':True}
    return comparisons


def build_online():
    if OUT.exists() or any(HERE.glob('nh-*-request.json')):
        raise RuntimeError('existing owned attempts/receipt: refuse duplicate NH queries; use offline replay')
    input_bytes=INPUT.read_bytes()
    original=json.loads(input_bytes.decode('utf-8'))
    snapshot={key:original[key] for key in ['input_hypotheses','requests','forward_comparison','model_identity','uncertainty_boundary','mass_radius_transfer','all_shell_boundary']}
    fo={};fo_archives={}
    for old in original['lookups']:
        key=old['id']
        if key not in ALLOWED or old['Z']!=60:raise ValueError('FO input outside authorized points')
        body=Path(old['html_path']).read_bytes()
        if hashlib.sha256(body).hexdigest()!=old['html_sha256']:raise ValueError('old FO response hash mismatch')
        record=parse_output(body,key,'BrIccFO')
        if record['alpha_T']['value']!=old['alpha_T_reported']['value'] or record['alpha_K']['value']!=old['alpha_K']['value']:
            raise ValueError('old FO numeric input mismatch')
        fo[key]=record;fo_archives[key]=packed(body)
    if set(fo)!=set(ALLOWED):raise ValueError('missing authorized FO baseline point')
    attempts=[];failures=[];queue=list(ORDER);stop_reason=None
    while queue:
        key=queue.pop(0)
        result=query_once(snapshot,key,len(attempts)+1)
        attempts.append(result)
        if result['failure']:
            failures.append({'case_id':key,**result['failure']})
            if len(failures)==1 and key=='B1-I18-401p2':
                # Different multipole/energy control, not a retry of the failed point.
                queue.remove('B1-I18-757p4');queue.insert(0,'B1-I18-757p4')
            if len(failures)>=2:
                stop_reason='two separate verified-protocol fixed-point diagnostic failures; causal details retained; stop without further retries or points'
                break
    nh={item['case_id']:item['parsed_NH'] for item in attempts if item['parsed_NH'] is not None}
    if stop_reason is None:stop_reason='completed each of the five bounded NH points once; no further query route opened'
    if INPUT.read_bytes()!=input_bytes:raise ValueError('old FO receipt changed during query')
    code=Path(__file__).read_text(encoding='utf-8')
    result={
        'schema_version':1,'created_at_utc':datetime.now(timezone.utc).isoformat(),
        'artifact_kind':'Day8-single-Day9-uncredited-preview-atomic-vacancy-sensitivity',
        'status':'five-authenticated-NH-inputs-with-coverage-boundaries' if len(nh)==5 else 'partial-or-failed-NH-certification-boundary',
        'run_day_index':8,'preview_day_index':9,'course_credit_changed':False,'run_closed':False,
        'experimental_data_fit':False,'mode_ranking_changed':False,'Day10_opened':False,
        'source':{'official_calculator':URL,'KB08_locator':'printed p207/PDF6 Sec4.1.1 FO/NH definitions',
                  'uncertainty_locator':'KB08 printed p206/PDF5 Table2 footnote; p213/PDF12 Sec5.1',
                  'coverage_locator':'KB08 printed p208/PDF7 Sec4.1.4 N6 boundary',
                  'input_receipt':str(INPUT.relative_to(ROOT)),'input_receipt_sha256':hashlib.sha256(input_bytes).hexdigest(),
                  'input_snapshot':snapshot,'new_literature_batch':False},
        'authentication_rule':'Actual program result version/model/Z/energy/pure-mode column plus numerical Tot/K must authenticate NH; HTTP200, form selection and request echo alone never suffice.',
        'lookup_statistics':{'new_NH_POST_attempts':len(attempts),'distinct_new_NH_points':len(attempts),'authenticated_NH_points':len(nh),
                             'new_FO_queries':0,'GET_queries':0,'retries':0,'failed_controls':len(failures),
                             'distinct_failure_causes':sorted({entry['cause'] for entry in failures}),
                             'maximum_authorized_points':5,'stop_reason':stop_reason},
        'FO_baseline':fo,'FO_exact_response_archives':fo_archives,
        'NH_attempts':attempts,'NH_authenticated_inputs':nh,
        'not_attempted':[key for key in ORDER if key not in {record['case_id'] for record in attempts}],
        'failures':failures,'forward_sensitivity':compare(snapshot,fo,nh),
        'forward_formulas':{'photon_g':'tau*Tgamma_i=g_i/[sum_j g_j(1+alpha_j)]',
                            'total_beta':'tau*Tgamma_i=beta_i/(1+alpha_i)',
                            'NH_over_FO_B_if_photon_g':'Dg_FO/Dg_NH; only for a complete parent inventory',
                            'NH_over_FO_B_if_total_beta':'(1+alpha_FO_i)/(1+alpha_NH_i)',
                            'B_relation':'At unchanged E, pure multipole,tau and same fraction hypothesis, B=Tgamma/[K_L E^(2L+1)], so the rate multiplier is exactly the nominal B multiplier; no constant or lifetime-unit inference is needed for the ratio.'},
        'boundaries':{'model':'FO/NH are vacancy treatments, not NP/no penetration. Both ordinary DF calculations use their nuclear-current approximation; no additional penetration fit is performed.',
                      'data_identity':'Provider-reported program dataset/version are authenticated. Remote binary/data-file hashes are not published/obtained; exact HTTP responses support offline retrieval replay.',
                      'shared_models':'All five outputs are theoretical inputs sharing atomic method/table assumptions. FO-NH spread is a deterministic model sensitivity, not an independent 1sigma or five experimental replications.',
                      'theory_uncertainty':'Adopted 1.4% includes interpolation; do not add the separate approximately0.3% interpolation accuracy again. No covariance matrix or full error budget is supplied.',
                      'printed_precision':'Sensitivity values are arithmetic from rounded program-reported Tot/K values. A displayed zero FO-NH difference means no difference resolved at that printing precision, not equality of unrounded physical calculations. Extra decimal digits in forward ratios are computational precision, not input or experimental precision.',
                      'coverage':'Preserve every returned N6 blank/warning and reported Tot, without filling zero or extrapolating. Forward rates using reported totals with missing-row warnings are nominal, not strict all-shell closure.',
                      'inventory':'Both given-number g and beta interpretations remain conditional on the complete listed branches and no extra uncounted decays; neither identifies MU08 actual processing.',
                      'mass_radius':snapshot['mass_radius_transfer'],
                      'author_assumptions':'Given pure-M1/E2 hypotheses are retained; no measured delta, higher-multipole exclusion or model ranking is created.',
                      'no_inverse_from_quoted_B':'No quoted B is used to identify the adopted atomic model, branching definition or penetration correction.'},
        'reproducibility':{'script_path':str(Path(__file__).relative_to(ROOT)),'script_sha256':hashlib.sha256(code.encode('utf-8')).hexdigest(),'source_code':code,
                           'offline_command':'python3 tmp/day8-20261007/day9-preview/vacancy-sensitivity/vacancy_sensitivity.py',
                           'online_first_execution_command':'python3 tmp/day8-20261007/day9-preview/vacancy-sensitivity/vacancy_sensitivity.py --online --write-receipt',
                           'offline_new_requests':0,'embedded_response_format':'gzip_base64 of exact response bytes plus SHA256/length',
                           'input_unchanged':True,'baseline_sha256':hashlib.sha256((RUN/'baseline.json').read_bytes()).hexdigest(),
                           'credentials_or_SSL_configuration_modified':False},
    }
    return result


def offline_replay():
    result=json.loads(OUT.read_text(encoding='utf-8'))
    fo={key:parse_output(unpacked(body),key,'BrIccFO') for key,body in result['FO_exact_response_archives'].items()}
    nh={};failed=[]
    for item in result['NH_attempts']:
        body=unpacked(item['response'])
        if item['failure'] is not None:
            if item['failure']['cause'] not in ('HTTP_failure','transport_or_size_failure'):
                try:parse_output(body,item['case_id'],'BrIccNH')
                except AuthenticationFailure as error:
                    if error.cause!=item['failure']['cause']:raise ValueError('offline failure classification mismatch')
                else:raise ValueError('cached failed output now authenticates unexpectedly')
            failed.append(item['case_id']);continue
        nh[item['case_id']]=parse_output(body,item['case_id'],'BrIccNH')
    comparison=compare(result['source']['input_snapshot'],fo,nh)
    if comparison!=result['forward_sensitivity']:raise ValueError('offline nominal comparison mismatch')
    if nh!=result['NH_authenticated_inputs']:raise ValueError('offline NH parser mismatch')
    code=result['reproducibility']['source_code'].encode('utf-8')
    if hashlib.sha256(code).hexdigest()!=result['reproducibility']['script_sha256']:raise ValueError('embedded source hash mismatch')
    print(json.dumps({'offline_replay':'passed','new_requests':0,'FO_tables':len(fo),'NH_authenticated':len(nh),
                      'failed_controls':failed,'receipt_status':result['status']},ensure_ascii=False,indent=2))


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--online',action='store_true')
    parser.add_argument('--write-receipt',action='store_true')
    args=parser.parse_args()
    if not args.online:
        if args.write_receipt:raise ValueError('offline replay does not overwrite any receipt')
        offline_replay();return
    result=build_online()
    if args.write_receipt:
        with OUT.open('x',encoding='utf-8',newline='\n') as stream:
            json.dump(result,stream,ensure_ascii=False,indent=2);stream.write('\n')
    print(json.dumps({'output':str(OUT.relative_to(ROOT)) if args.write_receipt else None,
                      'status':result['status'],'statistics':result['lookup_statistics'],
                      'NH_values':[{'id':key,'Tot':v['alpha_T']['reported'],'K':v['alpha_K']['reported'],'warnings':v['warnings']}
                                   for key,v in result['NH_authenticated_inputs'].items()],
                      'forward_sensitivity':result['forward_sensitivity'],'course_credit_changed':False,'run_closed':False},ensure_ascii=False,indent=2))


if __name__=='__main__':main()
